//! Real App reporting and focus from synchronous FORM validation methods.
use super::*;
struct Fixture(std::path::PathBuf);
impl Drop for Fixture{fn drop(&mut self){let _=std::fs::remove_file(&self.0);}}
fn node(app:&App,id:&str)->usize{(0..app.document.nodes.len()).find(|&n|app.document.attr(n,"id")==Some(id)).unwrap()}
fn click(app:&mut App,n:usize){let r=app.page.controls.iter().find(|r|r.node==n).unwrap();let(x,y)=(r.x+r.width/2,app.content_top()+r.y+r.height/2-app.scroll);app.pointer_down(x,y,false);app.pointer_up(x,y);}
#[test]
fn form_validation_actual_app_static_check_report_focus_editing_and_paint(){
 let file=Fixture(std::env::temp_dir().join(format!("chezcat-app-form-validation-{}.html",std::process::id())));
 std::fs::write(&file.0,r#"<!doctype html><style>body{background:white}input,button{display:block}#paint{position:absolute;left:420px;top:160px;width:40px;height:30px;background:#114455}#paint.done{background:#cc2244}#stable{position:absolute;left:420px;top:100px}</style><form id=owner novalidate><input id=edit name=q required><button id=check name=check type=button>Check</button><button id=report name=report type=button>Report</button></form><input id=neighbor value=neighbor><a id=stable href=#destination>Go</a><div id=paint></div><div id=destination></div><script>
 var form=document.getElementById('owner'),calls=0;form.addEventListener('invalid',function(e){if(!e.isTrusted||e.bubbles||!e.cancelable||e.composed)throw 'metadata';calls++;},true);document.getElementById('check').onclick=function(){if(form.checkValidity()!==false||calls!==1)throw 'synchronous check';document.title='Checked';};document.getElementById('report').onclick=function(){var valid=form.reportValidity();if(valid){document.getElementById('paint').className='done';document.title='Valid';}else{if(calls!==2)throw 'synchronous report';document.title='Reported';}};
 </script>"#).unwrap();
 let mut app=App::new();app.resize(640,480);app.set_javascript_enabled(true);app.open(&file.0);assert!(!app.failed&&!app.is_loading(),"{}",app.status);let edit=node(&app,"edit");let check=node(&app,"check");let report=node(&app,"report");let neighbor=node(&app,"neighbor");let stable=node(&app,"stable");let raw=app.raw.clone();let location=app.location.clone();let epoch=app.script_epoch;let r=app.page.controls.iter().find(|r|r.node==edit).unwrap();let rect=(r.x,r.y,r.width,r.height);app.forms.script_set_value(neighbor,"edited neighbor").unwrap();{let e=&mut app.forms.controls.get_mut(&neighbor).unwrap().value;e.cursor=5;e.anchor=2;e.offset=1;}
 let before=app.draw();click(&mut app,check);assert_eq!(app.document.title,"Checked");assert!(!app.failed);assert!(matches!(app.focus,Focus::Control(n)if n==check));click(&mut app,report);assert_eq!(app.document.title,"Reported");assert!(app.failed);assert_eq!(app.status,"Complete the required field: q.");assert!(matches!(app.focus,Focus::Control(n)if n==edit));for ch in ['A','😀','Z']{app.text_input(ch);}assert_eq!(app.forms.controls[&edit].value.text(),"A😀Z");click(&mut app,report);assert_eq!(app.document.title,"Valid");assert!(!app.is_loading());assert!(!app.failed);assert!(app.status.is_empty());assert_eq!(app.scripting.as_ref().unwrap().error_count(),0,"{}",app.scripting.as_ref().unwrap().report());let painted=app.draw();let pixel=(app.content_top()+170)as usize*painted.width+430;assert_eq!(painted.pixels[pixel],0xcc2244);assert_ne!(before.pixels[pixel],painted.pixels[pixel]);let e=&app.forms.controls[&neighbor].value;assert_eq!((e.text(),e.cursor,e.anchor,e.offset),("edited neighbor".into(),5,2,1));let r=app.page.controls.iter().find(|r|r.node==edit).unwrap();assert_eq!((r.x,r.y,r.width,r.height),rect);assert_eq!(app.page.link_node_at(430,110),Some(stable));assert_eq!((app.raw.clone(),app.location.clone(),app.script_epoch),(raw,location,epoch));
}
